ALTER TABLE "tasks" ADD COLUMN "coverImage" TEXT, ADD COLUMN "coverVersion" TEXT, ADD COLUMN "featured" BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE "promotions" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"image" TEXT NOT NULL,"destination" TEXT NOT NULL,"placement" TEXT NOT NULL DEFAULT 'banner' CHECK("placement" IN ('banner','ad')),"active" BOOLEAN NOT NULL DEFAULT TRUE,"startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endsAt" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK("endsAt" IS NULL OR "endsAt">"startsAt"));
